import {SUBJECTS,LESSONS,CONNECTIONS,THEORIES,PARTICLES,DISCOVERIES} from '../content/curriculum.mjs';
import {EQUATIONS} from '../content/equations.mjs';import {REFERENCES} from '../content/references.mjs';
import {EXPERIMENTS,experiment,createModel} from '../physics/registry.mjs';
import {ExperimentSession} from './session.mjs';import {ResearchStore} from '../storage/notebook.mjs';
import {SceneCanvas} from '../ui/scene.mjs';import {PlotCanvas} from '../ui/plot.mjs';
import {$,esc,fmt,option,math,badge,kinds,statuses,conversions,displayValue,scientificValue,notify} from '../ui/utils.mjs';
const clone=v=>structuredClone(v),levels=['intuitive','mathematical','advanced'];
const subject=id=>SUBJECTS.find(s=>s.id===id),titleCase=s=>String(s).replaceAll('-',' ');

class Axiom{
 constructor(){this.store=new ResearchStore({experimentIds:EXPERIMENTS.map(e=>e.id),lessonIds:LESSONS.map(l=>l.id),equationIds:EQUATIONS.map(e=>e.id),createModel});this.route='';this.session=null;this.renderer=null;this.plot=null;this.selected=null;this.unitChoices={};this.previews=[];this.filters={subject:'all',status:'all',difficulty:'all',prerequisite:'all'};this.searchTerm='';this.theoryTab='overview';this.lastFrame=performance.now();this.lastReadout=0;this.frameAverage=0;this.bind();this.applySettings();this.render();requestAnimationFrame(t=>this.frame(t));}
 bind(){$('.skip').onclick=e=>{e.preventDefault();$('#content').focus();};window.addEventListener('hashchange',()=>this.render());$('#global-search').oninput=e=>{this.searchTerm=e.target.value.trim();if(location.hash!=='#search')location.hash='search';else this.renderSearch();};$('#learning-level').onchange=e=>{this.store.settings({level:e.target.value});this.render();};document.addEventListener('visibilitychange',()=>{if(document.hidden)this.session?.pause();});window.addEventListener('pagehide',()=>this.session?.pause());}
 applySettings(){const s=this.store.data.settings;$('#learning-level').value=s.level;document.documentElement.dataset.reduced=String(s.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches);}
 go(route){if(location.hash==='#'+route)this.render();else location.hash=route;}
 sourceLinks(ids=[]){return `<ul class="references">${[...new Set(ids)].map(id=>{const r=REFERENCES.find(r=>r.id===id);return r?`<li><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a> · ${esc(r.institution)}${r.date?' · '+esc(r.date):''}<br>${esc(r.relevance)}</li>`:'';}).join('')}</ul>`;}
 heading(eyebrow,title,text=''){return `<div class="heading"><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1>${text?'<p>'+esc(text)+'</p>':''}</div>`;}
 subjectOptions(value='all'){return option('all','All disciplines',value==='all')+SUBJECTS.map(s=>option(s.id,s.title,value===s.id)).join('');}
 lessonCard(l){return `<article class="card"><span class="micro">${esc(subject(l.subject)?.title||l.subject)}</span><h3><a href="#lesson=${encodeURIComponent(l.id)}">${esc(l.title)}</a></h3>${badge(l.status)}<p>${esc(l.summary)}</p><div class="card-bottom"><span>${l.topics.length} connected topics</span><span>Mathematical depth ${l.difficulty}/3</span><a href="#lesson=${encodeURIComponent(l.id)}">Read & investigate →</a></div></article>`;}
 modelCard(e){return `<article class="card subject-card" style="--subject-color:${esc(subject(e.subject)?.color||'#78e6dc')}"><span class="micro">${esc(kinds[e.kind])} · ${esc(subject(e.subject)?.title||e.subject)}</span><h3><a href="#lab=${encodeURIComponent(e.id)}">${esc(e.title)}</a></h3>${badge(e.status)}<p>${esc(e.question||e.explanation||'Investigate the stated model and its limits.')}</p><div class="card-bottom"><a href="#lab=${encodeURIComponent(e.id)}">Open laboratory →</a></div></article>`;}
 render(){this.labVisible=false;this.session?.pause();this.renderer?.destroy();this.renderer=null;this.plot=null;for(const p of this.previews)p.destroy();this.previews=[];this.frozenGraph=null;const hash=location.hash.slice(1)||'home',[route,rawId]=hash.split('='),id=rawId?decodeURIComponent(rawId):'';this.route=route;this.routeId=id;for(const a of document.querySelectorAll('.navigation>a'))a.setAttribute('aria-current',a.hash==='#'+route||route==='lab'&&a.hash==='#labs'||route==='lesson'&&a.hash==='#library'||route==='equation'&&a.hash==='#equations'?'page':'false');this.applySettings();try{switch(route){case'home':this.renderHome();break;case'library':this.renderLibrary();break;case'labs':this.renderLabs();break;case'lab':this.renderLab(id);break;case'lesson':this.renderLesson(id);break;case'equations':this.renderEquations();break;case'equation':this.renderEquation(id);break;case'theories':this.renderTheories();break;case'graph':this.renderKnowledgeGraph(id);break;case'universe':this.renderUniverse();break;case'discoveries':this.renderDiscoveries();break;case'references':this.renderReferences();break;case'particles':this.renderParticles(id);break;case'notebook':this.renderNotebook();break;case'settings':this.renderSettings();break;case'search':this.renderSearch();break;default:$('#content').innerHTML=this.heading('NAVIGATION','Choose an institute section.');}}catch(error){$('#content').innerHTML=this.heading('MODEL / DATA NOTICE','This view could not open.',error.message);notify(error.message);console.error(error);}this.dirty=true;}
 renderHome(){const first=EXPERIMENTS.find(e=>e.id==='particle-box');$('#content').innerHTML=`<section class="hero"><div><p class="eyebrow">AN INSTITUTE FOR YOUR CURIOSITY</p><h1>The laws.<br>The questions.<br>The universe.</h1><p class="hero-subtitle">Explore the laws, forces, and mysteries of the universe.</p><p>Don’t just read physics. Experiment with it.</p><div class="actions"><a href="#labs">Explore the laboratories →</a><a href="#library">Open the Physics Library</a></div></div><div class="hero-visual"><canvas id="home-scene" aria-label="Actual particle-in-a-box model illustration"></canvas><small>Quantum particle in a box · a mathematical model, not a particle photograph</small></div></section><div class="stats"><span><b>${SUBJECTS.length}</b>disciplines</span><span><b>${EXPERIMENTS.length}</b>working laboratories</span><span><b>${LESSONS.length}</b>structured lessons</span><span><b>${EQUATIONS.length}</b>equations to explore</span></div><div class="section-title"><h2>Choose a field of inquiry.</h2><a href="#graph">Explore how the ideas connect →</a></div><div class="grid">${SUBJECTS.map(s=>`<article class="card subject-card" style="--subject-color:${esc(s.color)}"><span class="subject-icon">${esc(s.icon||'∿')}</span><h3><a href="#library" data-subject="${esc(s.id)}">${esc(s.title)}</a></h3><p>${esc(s.description)}</p><div class="card-bottom"><span>${LESSONS.filter(l=>l.subject===s.id).length} lessons · ${EXPERIMENTS.filter(e=>e.subject===s.id).length} laboratories</span><a href="#library" data-subject="${esc(s.id)}">Investigate →</a></div></article>`).join('')}</div><div class="section-title"><h2>Ways to investigate</h2></div><div class="grid">${[['references','Scientific References','Browse the primary textbooks, datasets and papers behind the institute.'],['particles','Particle Explorer','Inspect measured Standard Model particles and carefully qualified properties.'],['theories','Theory Explorer','Compare mathematical frameworks, evidence and open questions.'],['equations','Equation Explorer','Change meaningful parameters and follow the mathematics.'],['universe','Universe Simulator','Explore chosen cosmic models and stellar possibilities.'],['discoveries','Scientific Discoveries','Trace ideas that changed what science could explain.'],['notebook','My Research Notebook','Save configurations, actual graph data and your own observations.']].map(([r,t,d])=>`<article class="card"><h3><a href="#${r}">${t}</a></h3><p>${d}</p></article>`).join('')}</div><section class="panel" style="margin-top:25px"><h2>Know what kind of claim you are exploring.</h2><div class="evidence-key">${['established','approximation','unconfirmed','open-question'].map(badge).join('')}</div><p>Tested models have domains. Analogies can clarify mathematics without confirming a physical theory. Every laboratory states its assumptions and sources.</p></section>`;this.bindSubjectLinks();if(first){const view=new SceneCanvas($('#home-scene'));view.draw(createModel(first.id).scene());this.previews.push(view);}}
 bindSubjectLinks(){for(const a of document.querySelectorAll('[data-subject]'))a.onclick=()=>{this.filters.subject=a.dataset.subject;};}
 filterControls(){return `<div class="filters"><label>SUBJECT<select id="filter-subject">${this.subjectOptions(this.filters.subject)}</select></label><label>SCIENTIFIC STATUS<select id="filter-status">${option('all','All evidence states',this.filters.status==='all')+Object.entries(statuses).map(([v,l])=>option(v,l,this.filters.status===v)).join('')}</select></label><label>MATHEMATICAL DIFFICULTY<select id="filter-difficulty">${option('all','Any depth',this.filters.difficulty==='all')+[1,2,3].map(n=>option(n,['','Foundations','Mathematical','Advanced'][n],this.filters.difficulty===String(n))).join('')}</select></label><label>PREREQUISITES<select id="filter-prerequisite">${option('all','All lessons',this.filters.prerequisite==='all')+option('none','No prerequisites',this.filters.prerequisite==='none')+option('ready','Prerequisites marked read',this.filters.prerequisite==='ready')}</select></label></div>`;}
 bindFilters(render){for(const key of ['subject','status','difficulty','prerequisite'])$('#filter-'+key).onchange=e=>{this.filters[key]=e.target.value;render();};}
 matchingLessons(){return LESSONS.filter(l=>(this.filters.subject==='all'||l.subject===this.filters.subject)&&(this.filters.status==='all'||l.status===this.filters.status)&&(this.filters.difficulty==='all'||l.difficulty===+this.filters.difficulty)&&(this.filters.prerequisite==='all'||this.filters.prerequisite==='none'&&!l.prerequisites.length||this.filters.prerequisite==='ready'&&l.prerequisites.every(id=>this.store.data.readLessons.includes(id))));}
 renderLibrary(){$('#content').innerHTML=this.heading('PHYSICS LIBRARY','A connected map of nature.','Choose a discipline, evidence status or mathematical depth. Prerequisites guide your path; they do not lock access.')+this.filterControls()+`<p class="search-count">${this.matchingLessons().length} lessons</p><div class="grid">${this.matchingLessons().map(l=>this.lessonCard(l)).join('')||'<p class="empty">No lessons match these filters.</p>'}</div>`;this.bindFilters(()=>this.renderLibrary());}
 renderLabs(){const filtered=EXPERIMENTS.filter(e=>(this.filters.subject==='all'||e.subject===this.filters.subject)&&(this.filters.status==='all'||e.status===this.filters.status)&&(this.filters.difficulty==='all'&&this.filters.prerequisite==='all'||this.matchingLessons().some(l=>l.experimentIds.includes(e.id))));$('#content').innerHTML=this.heading('INTERACTIVE LABORATORIES','Change a variable. Ask a better question.','Run numerical models, inspect exact relationships, and distinguish a conceptual diagram from a physical prediction.')+this.filterControls()+`<p class="search-count">${filtered.length} laboratories · fixed model limits, actual data</p><div class="grid">${filtered.map(e=>this.modelCard(e)).join('')}</div>`;this.bindFilters(()=>this.renderLabs());}
 renderLesson(id){const l=LESSONS.find(l=>l.id===id);if(!l)throw Error('Lesson not found.');const level=this.store.data.settings.level;$('#content').innerHTML=this.heading(subject(l.subject)?.title||l.subject,l.title,l.summary)+badge(l.status)+`<div class="tabs" role="tablist" aria-label="Learning level">${levels.map(v=>`<button role="tab" data-level="${v}" aria-selected="${v===level}">${titleCase(v)}</button>`).join('')}</div><section class="panel prose"><p class="level-note">${level.toUpperCase()} LEVEL</p><p>${esc(l.levels[level]).replaceAll('\n','<br>')}</p><button id="mark-read" aria-pressed="${this.store.data.readLessons.includes(l.id)}">${this.store.data.readLessons.includes(l.id)?'✓ Marked read':'Mark this lesson read'}</button><h2>Ideas in this lesson</h2><div class="topic-list">${l.topics.map(t=>`<details><summary>${esc(t.title)}</summary><p>${esc(t.definition)}</p></details>`).join('')}</div><h2>Prerequisites & connections</h2><p>${l.prerequisites.length?l.prerequisites.map(id=>{const a=LESSONS.find(x=>x.id===id);return `<a href="#lesson=${encodeURIComponent(id)}">${esc(a?.title||id)}</a>`;}).join(' · '):'No prior lesson is required.'}</p><div class="study-links"><a href="#graph=${encodeURIComponent(l.id)}">Show this idea in the knowledge map →</a></div><h2>Equations</h2>${l.equationIds.map(id=>{const e=EQUATIONS.find(e=>e.id===id);return e?`<h3><a href="#equation=${id}">${esc(e.title)}</a></h3>${math(e.expression)}`:'';}).join('')}<h2>Investigate it</h2><div class="grid">${l.experimentIds.map(experiment).filter(Boolean).map(e=>this.modelCard(e)).join('')}</div>${l.subject==='particle'?'<p><a href="#particles">Open the Standard Model particle explorer →</a></p>':''}<h2>Scientific references</h2>${this.sourceLinks(l.references)}</section>`;for(const b of document.querySelectorAll('[data-level]'))b.onclick=()=>{this.store.settings({level:b.dataset.level});this.render();};$('#mark-read').onclick=()=>{this.store.toggleLesson(l.id);this.renderLesson(id);};}
 renderEquations(){const selected=this.filters.subject,items=EQUATIONS.filter(e=>selected==='all'||e.subject===selected);$('#content').innerHTML=this.heading('EQUATION EXPLORER','See the relationships.','Inspect symbols, units, dependencies and derivations. Operator and tensor equations use carefully selected solvable examples.')+`<div class="filters"><label>DISCIPLINE<select id="equation-subject">${this.subjectOptions(selected)}</select></label></div><div class="grid">${items.map(e=>`<article class="card"><span class="micro">${esc(subject(e.subject)?.title||e.subject)}</span><h3><a href="#equation=${e.id}">${esc(e.title)}</a></h3>${math(e.expression)}<small>${e.calculate?'Interactive selected calculation':'Guided mathematical interpretation'}</small></article>`).join('')}</div>`;$('#equation-subject').onchange=e=>{this.filters.subject=e.target.value;this.renderEquations();};}
 renderEquation(id){const e=EQUATIONS.find(e=>e.id===id);if(!e)throw Error('Equation not found.');this.equationValues=Object.fromEntries((e.parameters||[]).map(p=>[p.key,p.default]));$('#content').innerHTML=this.heading('EQUATION EXPLORER',e.title)+math(e.expression)+`<div class="actions"><button id="bookmark-equation" class="bookmark" aria-pressed="${this.store.data.bookmarks.includes(id)}">${this.store.data.bookmarks.includes(id)?'★ Bookmarked':'☆ Bookmark equation'}</button>${e.example?.experimentId?`<a href="#lab=${e.example.experimentId}">Open related laboratory →</a>`:''}</div><section class="panel prose" style="margin-top:20px"><h2>What the symbols mean</h2><table class="symbols"><thead><tr><th>Symbol</th><th>Meaning</th><th>Unit</th></tr></thead><tbody>${e.symbols.map(s=>`<tr><td>${esc(s.symbol)}</td><td>${esc(s.meaning)}</td><td>${esc(s.unit||'1')}</td></tr>`).join('')}</tbody></table><h2>Dependencies</h2><p>${esc(Array.isArray(e.dependencies)?e.dependencies.join(' · '):e.dependencies)}</p><h2>A guided derivation</h2><ol>${e.derivation.map(step=>'<li>'+esc(step)+'</li>').join('')}</ol><h2>Worked example</h2><p>${esc(e.example?.text||'See the associated model for a domain-qualified example.')}</p>${e.calculate?`<div class="formula-calculator"><div class="calc-inputs">${(e.parameters||[]).map(p=>`<label>${esc(p.label)} [${esc(p.unit||'1')}]<input type="number" step="any" data-equation-parameter="${p.key}" value="${p.default}" aria-label="${esc(p.label)}"></label>`).join('')}</div><div><div id="equation-result" class="result-box"></div><p id="equation-meaning"></p></div></div><div class="panel" style="margin-top:18px"><p class="micro">Parameter-dependency sweep · other inputs held fixed</p><canvas id="equation-plot" class="graph" aria-label="Calculated equation dependency graph"></canvas></div>`:'<p class="warning model-warning">This operator/tensor relationship is not reduced to an arbitrary scalar calculator. Use the stated derivation and selected laboratory example to inspect a solvable case.</p>'}<h2>Assumptions & validity</h2><ul>${e.assumptions.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><h2>References</h2>${this.sourceLinks(e.references)}</section>`;$('#bookmark-equation').onclick=()=>{this.store.toggleBookmark(id);this.renderEquation(id);};for(const input of document.querySelectorAll('[data-equation-parameter]'))input.oninput=()=>{this.equationValues[input.dataset.equationParameter]=Number(input.value);this.updateEquation(e);};if(e.calculate)this.updateEquation(e);}
 updateEquation(e){try{const result=e.calculate(this.equationValues);$('#equation-result').textContent=result.label+': '+fmt(result.value)+' '+result.unit;$('#equation-result').classList.remove('error');$('#equation-meaning').textContent=result.explanation;const parameter=e.parameters?.[0];if(parameter){const center=this.equationValues[parameter.key],span=Math.max(Math.abs(center)*.8,(parameter.max-parameter.min)*1e-6),low=Math.max(parameter.min,center-span),high=Math.min(parameter.max,center+span),points=Array.from({length:101},(_,i)=>{const x=low+(high-low)*i/100;try{return {x,y:e.calculate({...this.equationValues,[parameter.key]:x}).value};}catch{return {x,y:null};}});new PlotCanvas($('#equation-plot')).draw({points,x:{label:parameter.label,unit:parameter.unit},y:{label:result.label,unit:result.unit}});}}catch(error){$('#equation-result').textContent=error.message;$('#equation-plot').getContext('2d').clearRect(0,0,$('#equation-plot').width,$('#equation-plot').height);$('#equation-result').classList.add('error');$('#equation-meaning').textContent='No numerical prediction is shown outside the equation’s stated domain.';}}
 renderSearch(){const q=this.searchTerm.toLowerCase(),match=text=>String(text).toLowerCase().includes(q),lessons=q?LESSONS.filter(l=>match(l.title+' '+l.summary+' '+l.topics.map(t=>t.title+' '+t.definition).join(' '))):[],models=q?EXPERIMENTS.filter(e=>match(e.title+' '+e.question+' '+e.subject)):[],equations=q?EQUATIONS.filter(e=>match(e.title+' '+e.expression+' '+e.symbols.map(s=>s.meaning).join(' '))):[],particles=q?PARTICLES.filter(p=>match(p.name+' '+p.family+' '+p.symbol+' '+p.notes)):[],theories=q?THEORIES.filter(t=>match(t.title+' '+t.goals+' '+t.evidence)):[];$('#content').innerHTML=this.heading('GLOBAL SEARCH',q?'Results for “'+this.searchTerm+'”':'What would you like to investigate?','Search lessons and topics, laboratories, equations and theoretical frameworks.')+`<p class="search-count">${lessons.length+models.length+equations.length+theories.length+particles.length} matches</p>${lessons.length?'<h2>Lessons & topics</h2><div class="grid">'+lessons.map(l=>this.lessonCard(l)).join('')+'</div>':''}${models.length?'<h2>Laboratories</h2><div class="grid">'+models.map(e=>this.modelCard(e)).join('')+'</div>':''}${equations.length?'<h2>Equations</h2><div class="grid">'+equations.map(e=>`<article class="card"><h3><a href="#equation=${e.id}">${esc(e.title)}</a></h3>${math(e.expression)}</article>`).join('')+'</div>':''}${particles.length?'<h2>Particles</h2><div class="grid">'+particles.map(p=>`<article class="card"><h3><a href="#particles=${p.id}">${esc(p.name)}</a></h3><p>${esc(p.notes)}</p></article>`).join('')+'</div>':''}${theories.length?'<h2>Theoretical frameworks</h2><div class="grid">'+theories.map(t=>`<article class="card"><h3><a href="#theories">${esc(t.title)}</a></h3>${badge(t.status)}<p>${esc(t.evidence)}</p></article>`).join('')+'</div>':''}${q&&!lessons.length&&!models.length&&!equations.length&&!theories.length&&!particles.length?'<p class="empty">No matching topic was found. Try an equation name, a physical quantity or a discipline.</p>':''}`;}
 renderParticles(id){const selected=PARTICLES.find(p=>p.id===id),family=this.particleFamily||'all',items=PARTICLES.filter(p=>family==='all'||p.family===family);$('#content').innerHTML=this.heading('STANDARD MODEL','The particle explorer.','Measured particle families, quantum numbers and qualified masses. Unknown neutrino masses are not assigned zero.')+`<label>FAMILY<select id="particle-family">${['all',...new Set(PARTICLES.map(p=>p.family))].map(f=>option(f,titleCase(f),f===family)).join('')}</select></label><div class="grid" style="margin-top:20px">${items.map(p=>`<article class="card"><span class="subject-icon">${esc(p.symbol)}</span><h3><a href="#particles=${p.id}">${esc(p.name)}</a></h3><p>${esc(p.family)}</p><small>Charge ${p.id==='w'?'±1':fmt(p.charge)} e · spin ${p.spin} ℏ</small></article>`).join('')}</div>${selected?`<section class="panel prose" id="particle-detail" style="margin-top:24px"><h2>${esc(selected.name)} · ${esc(selected.symbol)}</h2>${badge(selected.status)}<p>Family: ${esc(selected.family)} · charge: ${selected.id==='w'?'±1':fmt(selected.charge)} e · spin: ${selected.spin} ℏ</p><p>Mass: ${selected.mass===null?'Individual absolute mass not asserted':fmt(selected.mass)+' '+esc(selected.massUnit)}</p><p>${esc(selected.notes)}</p>${this.sourceLinks(selected.references)}<a href="#lab=particle-decay">Investigate statistical decay →</a></section>`:''}`;$('#particle-family').onchange=e=>{this.particleFamily=e.target.value;this.renderParticles(id);};if(selected)$('#particle-detail').scrollIntoView({block:'nearest'});}
 renderLab(id){const def=experiment(id);if(!def)throw Error('Laboratory not found.');const pending=this.pendingConfig?.id===id?this.pendingConfig.config:null;if(!this.session||this.session.model.id!==id||pending){this.session=new ExperimentSession(createModel(id,pending||{}));this.unitChoices={};}this.pendingConfig=null;this.selected=id;this.session.frozen=false;this.labVisible=true;this.frozenGraph=null;this.graphMode=this.session.model.dynamic===false?'profile':'time';this.graphX=def.graph?.x||'time';this.graphY=def.graph?.y||Object.keys(this.session.model.measurementMeta).find(k=>k!=='time');const model=this.session.model;
  $('#content').innerHTML=`<div class="lab-heading">${this.heading(subject(def.subject)?.title||def.subject,def.title,def.question)}${badge(def.status)}</div><p class="level-note">${esc(kinds[def.kind])} · ${def.dynamic===false?'Adjust parameters to recalculate an analytical or conceptual model.':'Fixed physical clock; display speed does not change force laws.'}</p>${def.subject==='frontiers'?'<p class="warning"><b>UNCONFIRMED PHYSICAL FRAMEWORK</b><br>These classical analogies and geometric diagrams do not simulate quantum strings or establish extra dimensions of nature.</p>':''}<div class="lab-layout"><div class="lab-primary"><div class="viewport"><canvas id="scene" tabindex="0" aria-label="Interactive scientific visualization. Drag to pan, pinch or use buttons to zoom. Space runs or pauses; S single-steps; R resets."></canvas><div class="view-tools"><button id="fit-view">Fit view</button><button id="zoom-in" aria-label="Zoom view in">+</button><button id="zoom-out" aria-label="Zoom view out">−</button><small>Pan / zoom changes display only</small></div><p id="scene-caption" class="scene-caption"></p></div><div class="controls"><button id="run" class="primary">▶ Start</button><button id="pause">Pause</button><button id="single-step">Single step</button><button id="reset">Reset</button><label class="speed-label">Watch speed<select id="speed">${[.25,.5,1,2,4].map(v=>option(v,v+'×',v===this.session.speed)).join('')}</select></label></div><p id="clock" class="clock"></p><div id="model-warning" class="warning model-warning" hidden></div><section class="panel"><h3>What changes—and why?</h3><p id="model-explanation"></p><details><summary>${titleCase(this.store.data.settings.level)} learning notes</summary><p>${esc(LESSONS.find(l=>l.experimentIds.includes(id))?.levels[this.store.data.settings.level]||def.explanation||'Read the assumptions and the model’s linked equations to interpret its outputs.')}</p></details></section><section class="panel lab-plot"><div class="graph-controls"><label>PLOT<select id="plot-mode">${option('time','Actual time trace',this.graphMode==='time')+option('profile','Model curve / spatial field',this.graphMode==='profile')}</select></label><label>X VARIABLE<select id="graph-x"></select></label><label>Y VARIABLE<select id="graph-y"></select></label><button id="freeze-graph">Freeze graph</button><button id="clear-graph">Clear data</button></div><canvas id="graph" class="graph" aria-label="Scientific graph of actual measurements or calculated model data"></canvas><p id="graph-caption" class="graph-caption"></p></section><details class="panel"><summary>Governing equations</summary>${def.equationIds.map(id=>{const e=EQUATIONS.find(e=>e.id===id);return e?`<h3><a href="#equation=${id}">${esc(e.title)}</a></h3>${math(e.expression)}`:'';}).join('')||'<p>This is a conceptual geometric construction, not a numerical fundamental-physics prediction.</p>'}</details><details class="panel"><summary>Assumptions, validity & sources</summary><ul class="prose">${def.assumptions.map(s=>'<li>'+esc(s)+'</li>').join('')}</ul>${this.sourceLinks(def.references)}</details><section class="panel"><h3>Save this investigation</h3><div class="text-row"><label>OBSERVATION TITLE<input id="observation-title" maxlength="100" value="${esc(def.title)}"></label></div><label class="micro">YOUR OBSERVATIONS<textarea id="observation-text" maxlength="4000" placeholder="What did you vary? What does this model support, and what remains uncertain?"></textarea></label><div class="actions"><button id="save-experiment" class="primary">Save experiment & graph</button><a href="#notebook">Open research notebook →</a></div><p class="micro">Saves the initial configuration, actual readings and selected graph data. Restoring starts a fresh trial. Latest 30 observations are retained.</p></section></div><aside class="lab-inspector"><details class="panel" open><summary>PARAMETERS <span>↕</span></summary><label class="micro">PRESET<select id="preset" style="width:100%;margin:10px 0">${option('','Choose a configuration…')+(def.presets||[]).map((p,i)=>option(i,p.name)).join('')}</select></label><div id="parameters"></div></details><section class="panel readings-panel"><h3>Measurements & model outputs</h3><p class="micro">${def.kind==='C'?'Readouts describe the stated analogy or schematic only.':'SI quantities unless a scientific unit is explicitly stated.'}</p><div id="readings" class="readings"></div></section></aside></div>`;
  this.renderer=new SceneCanvas($('#scene'));this.plot=new PlotCanvas($('#graph'));this.renderParameters();this.populateGraphControls();this.bindLab();this.refreshLab();this.dirty=true;
 }
 renderParameters(){const def=experiment(this.selected),m=this.session.model;$('#parameters').innerHTML=def.parameters.map(p=>{if(p.type==='boolean')return `<div class="parameter"><label>${esc(p.label)}<input type="checkbox" data-parameter="${p.key}" ${m.config[p.key]?'checked':''}></label></div>`;if(p.type==='select')return `<div class="parameter"><label>${esc(p.label)}</label><select data-parameter="${p.key}" aria-label="${esc(p.label)}">${p.options.map(o=>option(o.value,o.label,m.config[p.key]===o.value)).join('')}</select></div>`;const ui=this.unitChoices[p.key]||0,units=conversions(p.unit),log=p.scale==='log'&&p.min>0,slider=log?Math.log10(m.config[p.key]):m.config[p.key];return `<div class="parameter"><label>${esc(p.label)}${units.length>1?`<select class="unit-select" data-unit="${p.key}" aria-label="${esc(p.label)} display unit">${units.map((u,i)=>option(i,u[0],ui===i)).join('')}</select>`:`<span class="micro">${esc(p.unit||'1')}</span>`}</label><input type="range" data-slider="${p.key}" aria-label="${esc(p.label)} slider" min="${log?Math.log10(p.min):p.min}" max="${log?Math.log10(p.max):p.max}" step="${log?'any':p.step||'any'}" value="${slider}"><input type="number" step="any" data-parameter="${p.key}" aria-label="${esc(p.label)} value" value="${displayValue(m.config[p.key],p.unit,ui)}"></div>`;}).join('');for(const el of document.querySelectorAll('[data-unit]'))el.onchange=()=>{this.unitChoices[el.dataset.unit]=Number(el.value);this.renderParameters();};for(const el of document.querySelectorAll('[data-parameter]'))el.onchange=()=>{const p=def.parameters.find(p=>p.key===el.dataset.parameter),value=p.type==='boolean'?el.checked:p.type==='select'?el.value:scientificValue(Number(el.value),p.unit,this.unitChoices[p.key]||0);this.rebuild({...this.session.model.config,[p.key]:value});this.renderParameters();};for(const slider of document.querySelectorAll('[data-slider]')){slider.oninput=()=>{const p=def.parameters.find(p=>p.key===slider.dataset.slider),value=p.scale==='log'&&p.min>0?10**Number(slider.value):Number(slider.value);if(this.rebuild({...this.session.model.config,[p.key]:value})){const field=$(`[data-parameter="${p.key}"]`);if(field)field.value=displayValue(value,p.unit,this.unitChoices[p.key]||0);}};slider.onchange=()=>this.renderParameters();}}
 rebuild(config){try{const m=createModel(this.selected,config),speed=this.session?.speed??1;this.session=new ExperimentSession(m);this.session.setSpeed(speed);$('#speed').value=String(this.session.speed);this.frozenGraph=null;this.renderer.fitted=false;$('#freeze-graph').textContent='Freeze graph';this.refreshLab();this.dirty=true;return true;}catch(error){notify(error.message);return false;}}
 populateGraphControls(){const meta=this.session.model.measurementMeta;$('#graph-x').innerHTML=Object.entries(meta).map(([key,m])=>option(key,m.label+' ['+(m.unit||'1')+']',key===this.graphX)).join('');$('#graph-y').innerHTML=Object.entries(meta).map(([key,m])=>option(key,m.label+' ['+(m.unit||'1')+']',key===this.graphY)).join('');if(!meta[this.graphX])this.graphX=$('#graph-x').value;if(!meta[this.graphY])this.graphY=$('#graph-y').value;const hasProfile=!!this.session.model.profile();$('#plot-mode option[value=profile]').disabled=!hasProfile;if(!hasProfile&&this.graphMode==='profile'){this.graphMode='time';$('#plot-mode').value='time';}$('#graph-x').disabled=$('#graph-y').disabled=this.graphMode==='profile';}
 currentGraph(){if(this.frozenGraph)return clone(this.frozenGraph);if(this.graphMode==='profile'){const p=this.session.model.profile();return p?{...p,mode:'profile'}:{mode:'profile',points:[],x:{label:'Coordinate',unit:'1'},y:{label:'Model value',unit:'1'},label:'No profile available'};}const meta=this.session.model.measurementMeta;return {mode:'time',points:this.session.history.map(r=>({x:r[this.graphX],y:r[this.graphY]})).filter(p=>Number.isFinite(p.x)&&(p.y===null||Number.isFinite(p.y))),x:meta[this.graphX],y:meta[this.graphY],label:'Actual fixed-step measurements'};}
 bindLab(){const session=()=>this.session;$('#run').onclick=()=>{session().play();this.dirty=true;this.refreshLab();};$('#pause').onclick=()=>{session().pause();this.refreshLab();};$('#single-step').onclick=()=>{session().step();this.refreshLab();this.dirty=true;};$('#reset').onclick=()=>this.rebuild(session().model.config);$('#speed').onchange=e=>{session().setSpeed(e.target.value);this.refreshLab();};$('#fit-view').onclick=()=>{this.renderer.fit(session().model.scene());this.dirty=true;};$('#zoom-in').onclick=()=>this.renderer.zoom(1.25);$('#zoom-out').onclick=()=>this.renderer.zoom(.8);$('#preset').onchange=e=>{if(e.target.value!==''){this.rebuild(experiment(this.selected).presets[+e.target.value].config);this.renderParameters();}};$('#plot-mode').onchange=e=>{this.graphMode=e.target.value;this.frozenGraph=null;session().frozen=false;$('#freeze-graph').textContent='Freeze graph';this.populateGraphControls();this.dirty=true;};for(const axis of ['x','y'])$('#graph-'+axis).onchange=e=>{this[axis==='x'?'graphX':'graphY']=e.target.value;this.frozenGraph=null;session().frozen=false;$('#freeze-graph').textContent='Freeze graph';this.dirty=true;};$('#freeze-graph').onclick=()=>{if(!this.frozenGraph){this.frozenGraph=clone(this.currentGraph());session().frozen=true;$('#freeze-graph').textContent='Resume graph';}else{this.frozenGraph=null;session().frozen=false;$('#freeze-graph').textContent='Freeze graph';}this.dirty=true;};$('#clear-graph').onclick=()=>{session().clear();if(this.frozenGraph)this.frozenGraph.points=[];this.dirty=true;};$('#save-experiment').onclick=()=>{try{this.store.saveExperiment({experimentId:this.selected,title:$('#observation-title').value,config:session().model.config,observations:$('#observation-text').value,readings:session().model.measure(),graph:this.currentGraph()});notify(this.store.error?'Saved in this session; persistence failed: '+this.store.error:'Experiment configuration, readings and graph saved.');}catch(error){notify(error.message);}};$('#scene').onkeydown=e=>{if(e.code==='Space'){e.preventDefault();session().running?session().pause():session().play();}else if(e.key.toLowerCase()==='s')session().step();else if(e.key.toLowerCase()==='r')this.rebuild(session().model.config);this.dirty=true;this.refreshLab();};}
 refreshLab(){if(!this.labVisible||!$('#readings'))return;const m=this.session.model,readings=m.measure();$('#readings').innerHTML=Object.entries(readings).map(([key,value])=>`<div class="reading"><span>${esc(m.measurementMeta[key]?.label||key)}</span><b>${fmt(value)} ${esc(m.measurementMeta[key]?.unit||'')}</b></div>`).join('');$('#model-explanation').textContent=m.explain();$('#run').disabled=m.dynamic===false||m.complete||m.valid===false||this.session.running;$('#pause').disabled=!this.session.running;$('#single-step').disabled=m.dynamic===false||m.complete||m.valid===false;$('#clock').textContent=m.dynamic===false?'Analytical / conceptual view · parameter changes recalculate immediately.':`t = ${fmt(m.time)} s · physical Δt ${fmt(m.dt)} s · nominal ${fmt(m.clockRate)} simulated s per real s at 1× · watch speed ${this.session.speed}× · ${this.session.running?'RUNNING':'PAUSED'}`;const warnings=[...m.warnings,...(this.session.error?[this.session.error]:[]),...(this.session.lagging?['Requested wall-clock pace exceeds this device’s update budget; the model slows rather than enlarging its physical time step.']:[])];$('#model-warning').hidden=!warnings.length;$('#model-warning').textContent=warnings.join(' ');}
 frame(time){const delta=(time-this.lastFrame)/1000;this.lastFrame=time;if(this.labVisible&&this.session&&this.renderer){const wasRunning=this.session.running;this.session.advance(delta);if(wasRunning||this.dirty){try{const start=performance.now(),quality=this.store.data.settings.quality,low=quality==='low'||quality==='auto'&&this.frameAverage>12;this.renderer.quality=this.plot.quality=low?'low':'high';const scene=this.session.model.scene();this.renderer.draw(scene);$('#scene-caption').textContent=scene.caption||'';if(!low||this.renderer.metrics.frames%2===0||this.dirty){const graph=this.currentGraph();this.plot.draw(graph);$('#graph-caption').textContent=(this.frozenGraph?'FROZEN · ':'')+(graph.label||'')+' · '+graph.points.length+' actual data points';}this.frameAverage=this.frameAverage*.9+(performance.now()-start)*.1;if(time-this.lastReadout>150||this.dirty){this.refreshLab();this.lastReadout=time;}this.dirty=false;}catch(error){this.session.pause();notify(error.message);}}}requestAnimationFrame(t=>this.frame(t));}
 renderUniverse(){$('#content').innerHTML=this.heading('UNIVERSE SIMULATOR','Choose a cosmic model.','Explore explicitly chosen expansion histories, mass distributions, spectral shifts and stellar pathways. Assumptions travel with every model.')+`<div class="grid">${EXPERIMENTS.filter(e=>e.subject==='cosmology'||['photon-path','lensing','schwarzschild-clocks'].includes(e.id)).map(e=>this.modelCard(e)).join('')}</div><section class="panel prose" style="margin-top:20px"><h2>Evidence and unanswered questions</h2><p>Dark-matter evidence and cosmological acceleration constrain models. They do not by themselves establish dark matter’s particle identity or the physical origin of dark energy.</p><div class="study-links">${LESSONS.filter(l=>l.subject==='cosmology').map(l=>`<a href="#lesson=${l.id}">${esc(l.title)}</a>`).join('')}</div>${this.sourceLinks(['esa-planck','nasa-cosmology'])}</section>`;}
 renderKnowledgeGraph(selectedId=''){const positions=new Map();SUBJECTS.forEach((s,i)=>{const lessons=LESSONS.filter(l=>l.subject===s.id),cx=120+(i%5)*240,cy=145+Math.floor(i/5)*300;lessons.forEach((l,n)=>{const a=-Math.PI/2+n/lessons.length*Math.PI*2;positions.set(l.id,{x:cx+70*Math.cos(a),y:cy+75*Math.sin(a)});});});const selected=LESSONS.find(l=>l.id===selectedId),linked=new Set([selectedId,...CONNECTIONS.filter(e=>e.from===selectedId||e.to===selectedId).flatMap(e=>[e.from,e.to])]);let svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 600" aria-label="Clickable graph of physics lessons and their connections">';for(const e of CONNECTIONS){const a=positions.get(e.from),b=positions.get(e.to);if(a&&b)svg+=`<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${selectedId&&(e.from===selectedId||e.to===selectedId)?'#bca5ee':'#42627b'}" opacity="${selectedId?.85:.35}"><title>${esc(e.label)}</title></line>`;}for(const [i,s]of SUBJECTS.entries())svg+=`<text x="${120+(i%5)*240}" y="${145+Math.floor(i/5)*300}" text-anchor="middle" fill="${esc(s.color)}" font-size="12" font-family="system-ui">${esc(s.title)}</text>`;for(const l of LESSONS){const p=positions.get(l.id);svg+=`<a href="#graph=${encodeURIComponent(l.id)}" aria-label="Explore ${esc(l.title)}" opacity="${!selectedId||linked.has(l.id)?1:.25}"><title>${esc(l.title)}</title><circle cx="${p.x}" cy="${p.y}" r="${l.id===selectedId?10:7}"/><text x="${p.x+11}" y="${p.y+3}">${esc(l.title.slice(0,23))}</text></a>`;}svg+='</svg>';$('#content').innerHTML=this.heading('KNOWLEDGE GRAPH','Ideas become clearer together.','Select a concept to highlight its connections. Prerequisites guide study without locking access.')+`<div class="knowledge-map">${svg}</div><section class="panel map-selection">${selected?`<h2>${esc(selected.title)}</h2><p>${esc(selected.summary)}</p><a href="#lesson=${selected.id}" class="button-link">Study this lesson →</a><h3>Connected ideas</h3><div class="study-links">${[...linked].filter(id=>id!==selectedId).map(id=>{const l=LESSONS.find(l=>l.id===id);return l?`<a href="#graph=${l.id}">${esc(l.title)}</a>`:'';}).join('')}</div>`:'<h2>Select any node</h2><p>Connections include prerequisites and bridges between mechanics, fields, spacetime, quantum theory and current research.</p>'}</section>`;}
 renderDiscoveries(){$('#content').innerHTML=this.heading('SCIENTIFIC DISCOVERIES','How the questions changed.','A history of scientific ideas and evidence—not a list of points to collect.')+`<div class="timeline">${DISCOVERIES.map(d=>`<article><time>${d.year}</time><h2>${esc(d.title)}</h2><p>${esc(d.description)}</p><a href="#lesson=${d.lessonId}">Explore the connected lesson →</a>${this.sourceLinks(d.references)}</article>`).join('')}</div>`;}
 renderTheories(){this.session?.pause();this.renderer?.destroy();this.renderer=null;this.plot=null;this.labVisible=false;const tabs=[['overview','Overview'],['strings','Strings & vibrations'],['open-closed','Open / closed strings'],['dimensions','Extra dimensions'],['branes','Branes'],['compare','Theory comparison'],['unknown','What remains unknown?']],navigation=this.heading('THEORY EXPLORER','Frameworks, evidence and open questions.','Understand what a mathematical framework aims to explain, what has been tested, and what remains unresolved.')+`<div class="tabs" role="tablist" aria-label="Theory Explorer sections">${tabs.map(([id,label])=>`<button role="tab" data-theory-tab="${id}" aria-selected="${this.theoryTab===id}">${label}</button>`).join('')}</div>`;const labId={strings:'classical-string','open-closed':'classical-string',dimensions:'compactification',branes:'branes'}[this.theoryTab];if(labId){this.renderLab(labId);$('#content').insertAdjacentHTML('afterbegin',navigation+'<div class="frontier-intro"><p class="eyebrow">THE STRING THEORY EXPLORER</p><h2>Illustrate the mathematics.<br>Keep the evidence distinct.</h2><p class="warning"><b>UNCONFIRMED PHYSICAL FRAMEWORK</b> · A classical vibration or geometric projection does not confirm quantum strings, branes or extra dimensions.</p></div>');if(this.theoryTab==='open-closed'){this.rebuild({...this.session.model.config,boundary:'periodic'});this.renderParameters();}}else if(this.theoryTab==='compare'){$('#content').innerHTML=navigation+`<section class="panel theory-comparison"><table class="symbols"><thead><tr><th>Framework</th><th>Goals & mathematics</th><th>Evidence status</th><th>Difficulties & questions</th></tr></thead><tbody>${THEORIES.map(t=>`<tr><td><b>${esc(t.title)}</b><br>${badge(t.status)}</td><td>${esc(t.goals)}<br>${esc(t.framework)}</td><td>${esc(t.evidence)}</td><td>${esc(t.difficulties)}<br>${t.questions.map(esc).join(' · ')}</td></tr>`).join('')}</tbody></table></section>`;}else if(this.theoryTab==='unknown'){$('#content').innerHTML=navigation+`<div class="frontier-intro"><h2>What remains unknown?</h2><p>Quantum gravity, the black-hole information problem and the physical relevance of proposed fundamental frameworks remain active research. Mathematical consistency and duality results are distinct from evidence that a model describes our universe.</p></div><div class="theory-grid">${THEORIES.filter(t=>t.status!=='established').map(t=>`<article class="card"><h3>${esc(t.title)}</h3>${badge(t.status)}<p>${esc(t.difficulties)}</p><ul class="prose">${t.questions.map(q=>'<li>'+esc(q)+'</li>').join('')}</ul>${this.sourceLinks(t.references)}</article>`).join('')}</div>`;}else{$('#content').innerHTML=navigation+`<div class="frontier-intro"><p class="eyebrow">THE STRING THEORY EXPLORER</p><h2>Beyond the familiar.</h2><p>Explore vibrations, compactification and branes with explicit analogies. String theory and M-theory are unconfirmed physical frameworks, not completed experimentally established theories of everything.</p><button id="open-string-explorer" class="primary">Enter the String Theory Explorer →</button></div><div class="theory-grid">${THEORIES.map(t=>`<article class="card"><h3>${esc(t.title)}</h3>${badge(t.status)}<p><b>Scientific goal:</b> ${esc(t.goals)}</p><p><b>Framework:</b> ${esc(t.framework)}</p><p><b>Evidence:</b> ${esc(t.evidence)}</p><details><summary>Limitations & open questions</summary><p>${esc(t.difficulties)}</p><ul class="prose">${t.questions.map(q=>'<li>'+esc(q)+'</li>').join('')}</ul>${this.sourceLinks(t.references)}</details></article>`).join('')}</div>`;$('#open-string-explorer').onclick=()=>{this.theoryTab='strings';this.renderTheories();};}for(const b of document.querySelectorAll('[data-theory-tab]'))b.onclick=()=>{this.theoryTab=b.dataset.theoryTab;this.renderTheories();};this.dirty=true;}
 renderNotebook(){$('#content').innerHTML=this.heading('MY RESEARCH NOTEBOOK','Keep the question with the result.','Saved initial configurations, actual graph samples, observations and personal notes. Restoring starts a fresh experiment; it does not restore an arbitrary live simulation state.')+`${this.store.error?'<p class="warning model-warning">'+esc(this.store.error)+'</p>':''}<div class="notebook-toolbar"><button id="compare-results">Compare selected results</button><button id="export-notebook">Export notebook JSON</button><button id="legacy-import">Import compatible PHYSICA setups</button></div><div id="comparison-result"></div><h2>Experiment observations</h2><p class="micro">Latest 30 observations · compare up to three with matching model, axes, units and graph kind.</p><div class="notebook-grid">${this.store.data.entries.slice().reverse().map(e=>`<article class="panel entry"><label><input type="checkbox" data-compare="${esc(e.id)}">Select for comparison</label><h3>${esc(e.title)}</h3><small>${esc(experiment(e.experimentId)?.title||e.experimentId)} · ${esc(new Date(e.savedAt).toLocaleString())}</small><p>${esc(e.observations||'No observation text recorded.')}</p><small>${e.graph.points.length} stored ${esc(e.graph.mode)} data points · ${esc(e.graph.y.label)} [${esc(e.graph.y.unit)}]</small><div class="entry-actions"><button data-restore="${esc(e.id)}">Restore initial setup</button><button data-inspect-graph="${esc(e.id)}">Inspect saved graph</button><button data-delete-entry="${esc(e.id)}">Delete observation</button></div><div id="saved-graph-${esc(e.id)}"></div></article>`).join('')||'<p class="empty">Save an investigation from any laboratory to begin.</p>'}</div><section class="panel" style="margin-top:25px"><h2>Personal research notes</h2><div class="note-editor"><label class="micro">TITLE<input id="note-title" maxlength="100" placeholder="A question to return to"></label><label class="micro">YOUR NOTE<textarea id="note-body" maxlength="4000" placeholder="Record a question, an interpretation, or a limitation of the model."></textarea></label><button id="save-note" class="primary">Save personal note</button></div>${this.store.data.notes.slice().reverse().map(n=>`<article class="entry"><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="entry-actions"><button data-edit-note="${esc(n.id)}">Edit note</button><button data-delete-note="${esc(n.id)}">Delete note</button></div></article>`).join('')}</section><section class="panel" style="margin-top:25px"><h2>Bookmarked equations</h2><div class="study-links">${this.store.data.bookmarks.map(id=>`<a href="#equation=${id}">${esc(EQUATIONS.find(e=>e.id===id)?.title||id)}</a>`).join('')||'<span class="micro">Bookmark equations while studying them.</span>'}</div><p class="micro">${this.store.data.readLessons.length} lessons marked read. This is a study record, not a score.</p></section><details class="panel" style="margin-top:25px"><summary>Portable notebook data</summary><p class="micro">Imports validate IDs, physical domains and bounded graph data, then merge without overwriting existing observations. Unknown versions or conflicting IDs are rejected.</p><textarea id="notebook-json" class="json-area" aria-label="Notebook JSON"></textarea><div class="actions"><button id="import-notebook">Validate & merge notebook JSON</button></div></details>`;
  for(const b of document.querySelectorAll('[data-restore]'))b.onclick=()=>{const e=this.store.data.entries.find(e=>e.id===b.dataset.restore);this.pendingConfig={id:e.experimentId,config:e.config};this.go('lab='+e.experimentId);};for(const b of document.querySelectorAll('[data-delete-entry]'))b.onclick=()=>{this.store.removeEntry(b.dataset.deleteEntry);this.renderNotebook();};for(const b of document.querySelectorAll('[data-inspect-graph]'))b.onclick=()=>{const e=this.store.data.entries.find(e=>e.id===b.dataset.inspectGraph),host=document.getElementById('saved-graph-'+e.id);host.innerHTML='<canvas class="graph" aria-label="Stored scientific graph"></canvas>';new PlotCanvas(host.querySelector('canvas')).draw(e.graph);};$('#compare-results').onclick=()=>this.compareResults();$('#export-notebook').onclick=()=>{try{$('#notebook-json').value=this.store.exportJSON();$('#notebook-json').closest('details').open=true;notify('Copy the versioned JSON to retain your notebook.');}catch(e){notify(e.message);}};$('#import-notebook').onclick=()=>{try{const count=this.store.importJSON($('#notebook-json').value);this.renderNotebook();notify(count+' records imported. '+(this.store.error||'Existing observations preserved.'));}catch(e){notify(e.message);}};$('#legacy-import').onclick=()=>this.importLegacy();this.editNoteId=null;$('#save-note').onclick=()=>{try{this.store.saveNote($('#note-title').value,$('#note-body').value,this.editNoteId);this.renderNotebook();notify(this.store.error||'Personal note saved.');}catch(e){notify(e.message);}};for(const b of document.querySelectorAll('[data-edit-note]'))b.onclick=()=>{const n=this.store.data.notes.find(n=>n.id===b.dataset.editNote);this.editNoteId=n.id;$('#note-title').value=n.title;$('#note-body').value=n.body;$('#note-title').focus();};for(const b of document.querySelectorAll('[data-delete-note]'))b.onclick=()=>{this.store.removeNote(b.dataset.deleteNote);this.renderNotebook();};}
 compareResults(){const ids=[...document.querySelectorAll('[data-compare]:checked')].map(e=>e.dataset.compare),entries=ids.map(id=>this.store.data.entries.find(e=>e.id===id));if(entries.length<2||entries.length>3){notify('Select two or three compatible observations.');return;}const first=entries[0],compatible=entries.every(e=>e.experimentId===first.experimentId&&e.graph.mode===first.graph.mode&&e.graph.x.unit===first.graph.x.unit&&e.graph.y.unit===first.graph.y.unit&&e.graph.x.label===first.graph.x.label&&e.graph.y.label===first.graph.y.label);if(!compatible){notify('Comparison requires the same model, graph type, axes and units.');return;}$('#comparison-result').innerHTML=`<section class="panel"><h2>Measured / calculated result comparison</h2><div class="plot-legend">${entries.map((e,i)=>`<span style="color:${['#78e6dc','#eec789','#b7a4f2'][i]}">${esc(e.title)}</span>`).join('')}</div><canvas id="comparison-graph" class="graph" aria-label="Compatible saved graph comparison"></canvas><p class="micro">Lines reproduce saved data. Different configurations may have different physical sample ranges.</p></section>`;new PlotCanvas($('#comparison-graph')).draw(first.graph,entries.slice(1).map((e,i)=>({...e.graph,color:['#eec789','#b7a4f2'][i]})));}
 importLegacy(){try{const raw=this.store.storage?.getItem('physica.progress.v1');if(!raw){notify('No PHYSICA saved setups are available on this browser origin.');return;}if(raw.length>1000000)throw Error('Legacy save is too large.');const data=JSON.parse(raw);if(data.v!==1||!Array.isArray(data.layouts))throw Error('Unsupported legacy save schema.');let imported=0,skipped=0;for(const layout of data.layouts.slice(0,8)){const d=EXPERIMENTS.find(e=>e.legacy?.lab===layout.lab&&e.legacy?.mode===layout.mode);if(!d||!layout.config||Object.keys(layout.config).some(k=>!d.parameters.some(p=>p.key===k))){skipped++;continue;}try{const m=createModel(d.id,layout.config),profile=m.profile(),keys=Object.keys(m.measurementMeta).filter(k=>k!=='time'),key=keys[0],graph=profile?{...profile,mode:'profile'}:{mode:'time',points:[],x:m.measurementMeta.time,y:m.measurementMeta[key]};this.store.saveExperiment({experimentId:d.id,title:String(layout.name||'Imported physics setup').slice(0,100),config:m.config,observations:'Imported initial setup only. Historical challenges and live simulation state were not transferred.',readings:m.measure(),graph});imported++;}catch{skipped++;}}this.renderNotebook();notify(`${imported} compatible setups imported; ${skipped} incompatible/free setups skipped. Original PHYSICA save is unchanged.`);}catch(error){notify(error.message);}}
 renderReferences(){$('#content').innerHTML=this.heading('SCIENTIFIC REFERENCES','Follow the evidence.','Primary textbooks, research papers, measurement reviews and institutional material. These optional links require an internet connection; the institute itself runs locally.')+`<div class="grid">${REFERENCES.map(r=>`<article class="card"><span class="micro">${esc(r.institution)}${r.date?' · '+esc(r.date):''}</span><h3><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a></h3><p>${esc(r.relevance)}</p></article>`).join('')}</div>`;}
 renderSettings(){$('#content').innerHTML=this.heading('SETTINGS','Make room for your way of studying.','Scientific steps remain independent of rendering quality, display scale and learning level.')+`<div class="settings-grid"><section class="panel"><h2>Reading and motion</h2><label>Learning level<select id="settings-level">${levels.map(l=>option(l,titleCase(l),l===this.store.data.settings.level)).join('')}</select></label><label>Reduce decorative motion<input id="settings-reduced" type="checkbox" ${this.store.data.settings.reduced?'checked':''}></label><p>Actual model evolution remains controlled by Start/Pause. Reduced motion suppresses interface transitions; it does not change physical equations or replace scientific time with arbitrary animation.</p><label>Rendering quality<select id="settings-quality">${option('auto','Adaptive',this.store.data.settings.quality==='auto')+option('high','High',this.store.data.settings.quality==='high')+option('low','Low',this.store.data.settings.quality==='low')}</select></label><p>Pixel ratio is capped; low quality draws graphs less often. If a device cannot keep the nominal simulation pace, bounded catch-up slows wall-clock progression rather than enlarging the numerical step.</p></section><section class="panel"><h2>Your data</h2><p>Research stays in this browser under AXIOM’s own notebook key. ELEMENTAL and PHYSICA data are never modified. Export notebook JSON to keep a portable copy.</p>${this.store.error?'<p class="warning model-warning">'+esc(this.store.error)+'</p>':''}<a href="#notebook" class="button-link">Open notebook & export →</a><h3>Evidence and limitations</h3><p>Scientific reference links are optional; all model/content assets load locally. Read each model’s assumptions before interpreting a result.</p><a href="README.md">Platform documentation →</a></section></div>`;$('#settings-level').onchange=e=>{this.store.settings({level:e.target.value});this.applySettings();};$('#settings-quality').onchange=e=>{this.store.settings({quality:e.target.value});notify(this.store.error||'Rendering preference saved.');};$('#settings-reduced').onchange=e=>{this.store.settings({reduced:e.target.checked});this.applySettings();};}
}

window.axiom=new Axiom();
